export interface MarkProps {
  className?: string;
  /** Accessible name; without it the mark is decorative (aria-hidden). */
  title?: string;
}

function Svg({
  viewBox,
  className,
  title,
  children,
}: MarkProps & { viewBox: string; children: React.ReactNode }) {
  return (
    <svg
      viewBox={viewBox}
      fill="currentColor"
      className={cn("w-3.5 h-3.5 shrink-0", className)}
      aria-hidden={title ? undefined : true}
      role={title ? "img" : undefined}
      focusable="false"
    >
      {title && <title>{title}</title>}
      {children}
    </svg>
  );
}

export function BrandIcon({
  brand,
  mono = true,
  className,
  ...props
}: MarkProps & {
  brand: Brand;
  /** Monochrome by default; false keeps the source's brand colors. */
  mono?: boolean;
}) {
  if (brand === "slack") {
    return (
      <Svg viewBox="0 0 24 24" className={className} {...props}>
        {SLACK_PATHS.map(([color, d]) => (
          <path key={color} d={d} fill={mono ? undefined : color} />
        ))}
      </Svg>
    );
  }
  return (
    <Svg viewBox="0 0 24 24" className={cn(!mono && BRAND_TINT[brand], className)} {...props}>
      <path d={BRAND_PATHS[brand]} />
    </Svg>
  );
}

const BRAND_TINT: Record<Brand, string> = {
  github: "text-text-heading",
  gitlab: "text-[#FC6D26]",
  slack: "text-text-heading",
  linear: "text-[#5E6AD2]",
  jira: "text-[#2684FF]",
  notion: "text-text-heading",
  sentry: "text-text-heading",
  bitbucket: "text-[#2684FF]",
  aws: "text-[#FF9900]",
  pagerduty: "text-[#06AC38]",
  postgresql: "text-[#336791]",
  pylon: "text-text-heading",
};

/** A provider / source string ("github", "GitLab", "linear", …) → its brand, if we have one. */
export function brandFor(provider: string | null | undefined): Brand | null {
  const p = (provider ?? "").toLowerCase();
  return Object.hasOwn(BRAND_LABEL, p) ? (p as Brand) : null;
}

/** Brand component for a provider, usable wherever a lucide icon component is expected. */
export function brandIconComponent(brand: Brand): ComponentType<MarkProps> {
  return BRAND_COMPONENTS[brand];
}

const BRAND_COMPONENTS = Object.fromEntries(
  (Object.keys(BRAND_LABEL) as Brand[]).map((b) => {
    const C = (p: MarkProps) => <BrandIcon brand={b} {...p} />;
    C.displayName = `BrandIcon(${b})`;
    return [b, C];
  }),
) as Record<Brand, ComponentType<MarkProps>>;

