/** GitHub's colors for PR / issue state: green open, purple merged / done, red closed. */
export const PR_STATE_TINT: Record<PrState, string> = {
  open: "text-success",
  merged: "text-[#8957e5]",
  closed: "text-error",
  draft: "text-text-muted",
};

/** Normalize the various PR state strings the API returns. Unknown → open. */
export function prStateOf(state: string | null | undefined): PrState {
  const s = (state ?? "").toLowerCase();
  if (s === "merged") return "merged";
  if (s === "closed" || s === "declined") return "closed";
  if (s === "draft") return "draft";
  return "open";
}

export function PrIcon({
  state = "open",
  colored = true,
  className,
  ...props
}: MarkProps & { state?: PrState | string | null; colored?: boolean }) {
  const s = prStateOf(state);
  return (
    <Svg viewBox="0 0 16 16" className={cn(colored && PR_STATE_TINT[s], className)} {...props}>
      <path d={PR_PATHS[s]} />
    </Svg>
  );
}

export type IssueState = "open" | "closed";

export function IssueIcon({
  state = "open",
  colored = true,
  className,
  ...props
}: MarkProps & { state?: IssueState | string | null; colored?: boolean }) {
  const closed = (state ?? "").toLowerCase() === "closed";
  return (
    <Svg
      viewBox="0 0 16 16"
      className={cn(colored && PR_STATE_TINT[closed ? "merged" : "open"], className)}
      {...props}
    >
      {closed ? (
        <>
          <path d="M11.28 6.78a.75.75 0 0 0-1.06-1.06L7.25 8.69 5.78 7.22a.75.75 0 0 0-1.06 1.06l2 2a.75.75 0 0 0 1.06 0l3.5-3.5Z" />
          <path d="M16 8A8 8 0 1 1 0 8a8 8 0 0 1 16 0Zm-1.5 0a6.5 6.5 0 1 0-13 0 6.5 6.5 0 0 0 13 0Z" />
        </>
      ) : (
        <>
          <path d="M8 9.5a1.5 1.5 0 1 0 0-3 1.5 1.5 0 0 0 0 3Z" />
          <path d="M8 0a8 8 0 1 1 0 16A8 8 0 0 1 8 0ZM1.5 8a6.5 6.5 0 1 0 13 0 6.5 6.5 0 0 0-13 0Z" />
        </>
      )}
    </Svg>
  );
}

// ── Triggers ────────────────────────────────────────────────────────────────

/**
 * The icon for a trigger type: the brand mark for the event sources (github /
 * slack / linear, and a ticket trigger whose source is known), the lucide
 * icons for the generic ones (manual / schedule / webhook / ticket).
 * `source` is a ticket trigger's provider (`config.source`).
 */
export function triggerTypeIcon(
  type: string | null | undefined,
  source?: string | null,
): ComponentType<{ className?: string }> {
  const brand = brandFor(type) ?? (type === "ticket" ? brandFor(source) : null);
  if (brand) return BRAND_COMPONENTS[brand];
  switch (type) {
    case "manual":
      return Play;
    case "schedule":
      return Clock;
    case "webhook":
      return Webhook;
    case "ticket":
      return Ticket;
    default:
      return Zap;
  }
}

/** Short label for a trigger type: "GitHub", "Slack", "Linear ticket", "schedule", … */
export function triggerLabel(type: string | null | undefined, source?: string | null): string {
  const brand = brandFor(type);
  if (brand) return BRAND_LABEL[brand];
  if (type === "ticket") {
    const src = brandFor(source);
    return src ? `${BRAND_LABEL[src]} ticket` : "ticket";
  }
  return type ?? "trigger";
}

export function TriggerIcon({
  type,
  source,
  className,
  colored = false,
}: {
  type: string | null | undefined;
  source?: string | null;
  className?: string;
  colored?: boolean;
}) {
  const brand = brandFor(type) ?? (type === "ticket" ? brandFor(source) : null);
  if (colored && brand) return <BrandIcon brand={brand} mono={false} className={className} />;
  const Icon = triggerTypeIcon(type, source);
  return <Icon className={cn("w-3.5 h-3.5 shrink-0", className)} />;
}

